#!/usr/bin/env python3
# =====================================================================
#  apply_exit_once.py  —  fence EXIT_ONCE_ALL_20261115
#  REQUIRES apply_instance_guard.py (INSTANCE_GUARD_20261115) — the full
#  round-3 chain: exit_latency → order_once → blind_stop → reserve_signed →
#  instance_guard → this.
#
#  Tracker T2 + D12, all four strategies. The app killed while an exit order
#  was being sent (order at Kite, its id not yet saved): after the restart
#  the exit was sent AGAIN. On a shared strike that bought back the other
#  strategy's short (seen in tests for Icarus, Timberwolf, Velvet, Tigris).
#  Now: just before each live exit order a tiny note is written ("exit for
#  <group/leg> on its way, tag ST…") and the order is sent under that tag.
#  After a restart, before sending an exit for the same leg:
#    order with that tag in Kite's book → THAT order is driven, nothing sent;
#    book unreadable (or noted < 1 min ago) → nothing sent this attempt;
#    not there → it never reached Kite → sent once.
#  A filled earlier order is not counted twice when the quantity was read
#  from the net position (sole holder). If the note file itself fails, exits
#  go out exactly as before.
#  Cost: one small file write (~0.4 ms, no fsync) per live exit order. No
#  extra broker call on a normal exit (budget test).
#
#   execution/broker_truth.py, instance_guard.py, zerodha_executor.py
#   engine/tsg/tsg_manager.py, ic/ic_group_manager.py,
#   tma2/tma2_trade_manager.py, vet/vet_manager.py
#   execution/testkit_fake_kite.py, engine/test_fleet_live.py (test kit)
#   NEW engine/test_tigris_exit_restart.py (21 checks, 3 fail on old code)
#   NEW engine/test_exit_once_restart.py   (19 checks, 10 fail on old code)
#
#  Run ONLY this script, outside market hours:
#     cd ~/dev/scalp-app && python3 apply_exit_once.py
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then: ./desktop/build-scalp.sh both, restart the app.
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "EXIT_ONCE_ALL_20261115"
ITEMS = json.loads(r'''[{"path": "backend/app/engine/ic/ic_group_manager.py", "orig": "4d4757a079ed27f41ecb1053e8664c6227b200d34d0f6b16cdeb5fb2acc9587d", "new": "eea5cf6ad89a8b3fb9918a5c0e483ca64de038206840e974f6b03739fdabe504", "blob": ""}, {"path": "backend/app/engine/test_exit_once_restart.py", "orig": null, "new": "12a05eeea14d26c985c99b7700d4e296bb6f1565e058a9a49c07a4e80c7ba929", "blob": ""}, {"path": "backend/app/engine/test_fleet_live.py", "orig": "db9827d82b819f82e42fd0fc2729a3e144b533632de9da0a06228622161822df", "new": "9ec97d1874837c04b165deb95cf989f47848651ac52b04a817abd93121262d9f", "blob": ""}, {"path": "backend/app/engine/test_tigris_exit_restart.py", "orig": null, "new": "fbe6462a4bd1fed18403f09572a1418d0bbd53b8670051fa6508f96b57168f39", "blob": ""}, {"path": "backend/app/engine/tma2/tma2_trade_manager.py", "orig": "d27d7b0a2a99c9a7eefa7f1dae4f032b1e205da17034b44228c54233a543bf4d", "new": "a5265162403d3a29a78e7ae47a026670b9989e37b25769be335ea15765f84a78", "blob": ""}, {"path": "backend/app/engine/tsg/tsg_manager.py", "orig": "b065dd6b6cbc821a414055e4441ed837de5a5c2b1cd23e0c9351217f207fc337", "new": "f603b4dfb8671b537d89511da0099747fcfa0cc88fab078bfa3d57ad3b0a698b", "blob": ""}, {"path": "backend/app/engine/vet/vet_manager.py", "orig": "039ce0e97817d075a5563b40ac89efae84bd049bb3cd5963f3395ce643a4779a", "new": "62b07023b1e4eab824457fd8012cadd637e4dfefd73d2051575b77598a9e30bf", "blob": ""}, {"path": "backend/app/execution/broker_truth.py", "orig": "8083c8b4c0932ee3e2f7a13d40d29afdd72358d576579076a75d6a7ef4fad658", "new": "f48c58bd8c44d20c8498d2cc5ae250b801f1e685256ebcb87f97d21bcaf1cb38", "blob": ""}, {"path": "backend/app/execution/instance_guard.py", "orig": "b3a4f204fa18c8007ba7caefb4aa59e0d737b0fe003082b957189ed30f599ea4", "new": "adec736d8fe52fed1d1a2b8b618995420cea20707fdee76280f80a5820b12d01", "blob": ""}, {"path": "backend/app/execution/test_instance_guard.py", "orig": "bf39d976c98eb98dedc2ede3bcc2bc7e026d52bb416507b4f47547712c321294", "new": "ddcfe06c6531a55f0389fb0f344ce3d5a934085e949f38fd46407b15a1457e6e", "blob": ""}, {"path": "backend/app/execution/testkit_fake_kite.py", "orig": "bc6bcd255a9b1c18a347e59ba5a102e0d08a8fb47ea728a2fe8748be29851c81", "new": "57653f2eaf62c0ae0c797cf54e911373317d5ed17cc8ae9267ffab2784382c5e", "blob": ""}, {"path": "backend/app/execution/zerodha_executor.py", "orig": "b615e5c0acaff73a72e7eb9516306cc347bbceece568c16910a9a3c2b5a0ec6b", "new": "96b3624d4158039da3ac527fbf21cc01feb17ba0c87ec56fa5e0fa024dc300f4", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = [         "app/engine/test_exit_once_restart.py",
         "app/engine/test_tigris_exit_restart.py",
         "app/engine/tsg/test_tsg_exit_confirm.py",
         "app/engine/tsg/test_tsg_e2e.py",
         "app/engine/vet/test_vet_live_confirm.py",
         "app/engine/vet/test_vet_e2e.py",
         "app/engine/tma2/test_tma2_exit_paths.py",
         "app/engine/tma2/test_tma2_e2e.py",
         "app/engine/ic/test_ic_gtt_strict.py",
         "app/execution/test_instance_guard.py",
         "app/execution/test_order_once.py",
         "app/execution/test_blind_stop.py",
         "app/engine/test_fleet_live.py",
         "app/engine/test_fleet_adversarial.py",
         "app/engine/test_order_path_budget.py",
         "app/engine/test_entry_reservation.py"
]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── prerequisite: apply_instance_guard.py (INSTANCE_GUARD_20261115)
if "--rollback" not in args:
    _pf = os.path.join(repo, *['backend', 'app', 'execution', 'zerodha_executor.py'])
    if not os.path.exists(_pf) or 'INSTANCE_GUARD_20261115' not in open(_pf, encoding="utf-8").read():
        die("needs apply_instance_guard.py (INSTANCE_GUARD_20261115) — this script builds on it")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped = [], 0, []
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}) — nothing to do")
    sys.exit(0)

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="exit_once_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend, SCALP_TEST_MODE="1")
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=900)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_exit_once.py --rollback")
